def mkkey(type, id):
    return type + ':' + id

def mkprogkey(user, id):
    return 'program:' + user + ':' + id

def mkfilekey(user, id):
    return id.encode("UTF-8") + "." + user

def make_pid(program):
    salt = random.randint(0, 1000000)
    js = json.dumps(program) + str(salt)
    md5 = hashlib.md5(js).hexdigest()
    return md5


