import os
base = "db.store"

def put(pid, contents):
    path = get_path(pid)
    dirname = os.path.dirname(path)
    if not os.path.exists(dirname):
        os.makedirs(dirname)
    f = open(path, "w")
    f.write(contents)
    f.close()

    return True

def delete(pid):
    path = get_path(pid)
    if os.path.exists(path):
        os.remove(path)

def get(pid):
    path = get_path(pid)
    if os.path.exists(path):
        f = open(path, "r")
        contents = f.read()
        f.close()
        return contents
    else:
        return None


def get_path(pid):
    if len(pid) < 4:
        path = os.sep.join([base, pid])
    else:
        path = os.sep.join([base, pid[0:2], pid[2:4], pid])
    return path

